import { reactive, ref } from 'vue'
import { debounce } from 'lodash-es'
import type { FetchFn, ProTableState } from './types'

export function useProTable(fetch: FetchFn, options = {}) {
  const loading = ref(false)
  const state = reactive<ProTableState>({ page: 1, pageSize: 20, total: 0 })
  const dataSource = ref<Record<string, unknown>[]>([])

  async function run(next = {}) {
    loading.value = true
    try {
      const { items, total } = await fetch({ ...state, ...next })
      dataSource.value = items
      state.total = total
    } finally {
      loading.value = false
    }
  }

  // 检索请求防抖 300ms，避免连打关键字打爆接口
  const search = debounce(run, 300)
  return { loading, dataSource, pagination: state, run, search }
}

