import type { TableColumnProps } from 'ant-design-vue'

/** 列定义工厂：操作列宽度按动作数自适应，避免手写魔法值 */
export function useColumns(rowActions?: string[]): TableColumnProps[] {
  const base: TableColumnProps[] = [
    { title: '时间', dataIndex: 'time', width: 120 },
    { title: '源 IP', dataIndex: 'src', width: 130 },
    { title: '告警类型', dataIndex: 'type' },
  ]
  if (!rowActions?.length) return base
  return [...base, { title: '操作', key: 'action', width: 60 + rowActions.length * 48 }]
}

/** 从告警原文提取结构化字段：优先 CEF 扩展键，退化到 LEEF/键值对 */
export function extractAlertFields(raw: string) {
  const pick = (key: string) => raw.match(new RegExp(key + '=([^\s]+)'))?.[1]

  return {
    src: pick('src') ?? null,
    dst: pick('dst') ?? null,
    port: Number(pick('spt') ?? 0),
    severity: pick('severity') ?? inferByKeyword(raw),
    raw: raw.length > 512 ? raw.slice(0, 512) + '…' : raw,
  }
}

function inferByKeyword(raw: string): string {
  if (/flood|scan|brute/i.test(raw)) return 'high'
  if (/policy|violation/i.test(raw)) return 'medium'
  return 'low'
}

import { onUnmounted } from 'vue'

export function useDebounceFn<T extends (...args: any[]) => void>(fn: T, delay = 300) {
  let timer: ReturnType<typeof setTimeout> | null = null

  const run = (...args: Parameters<T>) => {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => fn(...args), delay)
  }

  // 组件卸载顺手清掉定时器，避免内存里挂着幽灵回调
  onUnmounted(() => timer && clearTimeout(timer))
  return run
}

public class Result<T> {

    private String code;
    private String message;
    private T data;

    public static <T> Result<T> ok(T data) {
        Result<T> r = new Result<>();
        r.code = "00000";
        r.message = "success";
        r.data = data;
        return r;
    }

    public static <T> Result<T> fail(String code, String message) {
        Result<T> r = new Result<>();
        r.code = code;
        r.message = message;
        return r;
    }
}
